#!/usr/bin/env python3
"""Validate .pi/mcp.json.example against pi-mcp-adapter's ServerEntry contract.

Two silent failures this guards. First, a Claude Code entry pasted verbatim
carries `"type": "http"`, a field pi has no idea about, so the transport ends up
decided by whichever of command/url survived the paste. Second, an includeTools
allowlist is fail-closed: a misspelled tool name grants nothing and the server
still connects, so the pane looks healthy and the tool is simply gone.

Usage: check-mcp-template.py <template> <mcp-servers.manifest.json>
"""

import json
import sys
from pathlib import Path

# Prefixes of the real keys for the servers this template configures. A template
# is copied verbatim, so a literal key here becomes a committed key downstream.
KEY_MARKERS = ("ctx7sk-", "tvly-")


def main(template: Path, attested_path: Path) -> None:
    example = json.loads(template.read_text())
    attested = json.loads(attested_path.read_text())["configured"]

    servers = example.get("mcpServers")
    if not isinstance(servers, dict) or not servers:
        raise SystemExit("FAIL: template has no mcpServers")

    for name, entry in servers.items():
        if "type" in entry:
            raise SystemExit(
                f"FAIL: {name} has a `type` key; pi's ServerEntry has no such field "
                "(stdio is command+args, HTTP is url)"
            )
        if entry.get("disabled") is True:
            continue
        if not (entry.get("command") or entry.get("url") or entry.get("socket")):
            raise SystemExit(f"FAIL: {name} defines no transport (command, url or socket)")

        allowed = entry.get("includeTools")
        if allowed is None:
            if entry.get("$allowAll") is not True:
                raise SystemExit(
                    f'FAIL: {name} has no includeTools and no explicit "$allowAll": true. '
                    "An unrestricted server in a read-only template must say so on purpose."
                )
            continue
        if not isinstance(allowed, list) or not allowed:
            raise SystemExit(f"FAIL: {name} includeTools must be a non-empty array")

        roster = attested.get(name, {}).get("tools")
        if roster is None:
            # Nobody has verified this server's tool names. Inventing a roster to
            # check against would be worse than checking nothing.
            continue
        unknown = [tool for tool in allowed if tool not in roster]
        if unknown:
            raise SystemExit(
                f"FAIL: {name} allowlists names absent from the attested roster in "
                f"tests/agents/mcp-servers.manifest.json: {unknown}"
            )

    blob = template.read_text()
    for marker in KEY_MARKERS:
        if marker in blob:
            raise SystemExit(f"FAIL: template contains a literal API key ({marker})")


if __name__ == "__main__":
    main(Path(sys.argv[1]), Path(sys.argv[2]))
